{"CommandLine":"# Check WSL / Docker vhdx
$vhdx = Get-ChildItem -Path "$env:USERPROFILE\AppData\Local\Docker", "$env:USERPROFILE\AppData\Local\Packages" -Filter "*.vhdx" -Recurse -ErrorAction SilentlyContinue | Select-Object FullName, @{N="SizeGB";E={[math]::Round($_.Length/1GB, 2)}}

# Check Recycle Bin
$recycleBinSize = (Get-ChildItem -Path 'C:\$Recycle.Bin' -Recurse -Force -File -ErrorAction SilentlyContinue | Measure-Object -Property Length -Sum).Sum
$recycleBinGB = [math]::Round($recycleBinSize / 1GB, 2)

# Check AppData Local top folders
$appDataLocal = Get-ChildItem -Path "$env:LOCALAPPDATA" -Directory -ErrorAction SilentlyContinue | ForEach-Object {
    $dir = $_
    $s = (Get-ChildItem -Path $dir.FullName -Recurse -File -ErrorAction SilentlyContinue | Measure-Object -Property Length -Sum).Sum
    [PSCustomObject]@{
        Name = $dir.Name
        Path = $dir.FullName
        SizeGB = [math]::Round($s / 1GB, 2)
    }
} | Sort-Object SizeGB -Descending | Select-Object -First 10

[PSCustomObject]@{
    RecycleBinGB = $recycleBinGB
}
$vhdx
$appDataLocal
